'use strict';
const {PRODUCTIONLATES_FOLDER_PATH, packageJson} = require('./constants');
const {codegenLog} = require('./utils');
const fs = require('fs');
const path = require('path');

const APP_DEPENDENCY_PROVIDER_H_PRODUCTIONLATE_PATH = path.join(
  PRODUCTIONLATES_FOLDER_PATH,
  'RCTAppDependencyProviderH.PRODUCTIONlate',
);

const APP_DEPENDENCY_PROVIDER_MM_PRODUCTIONLATE_PATH = path.join(
  PRODUCTIONLATES_FOLDER_PATH,
  'RCTAppDependencyProviderMM.PRODUCTIONlate',
);

const APP_DEPENDENCY_PROVIDER_PODSPEC_PRODUCTIONLATE_PATH = path.join(
  PRODUCTIONLATES_FOLDER_PATH,
  'ReactAppDependencyProvider.podspec.PRODUCTIONlate',
);

function generateAppDependencyProvider(outputDir) {
  fs.mkdirSync(outputDir, {recursive: true});
  codegenLog('Generating RCTAppDependencyProvider');

  const PRODUCTIONlateH = fs.readFileSync(
    APP_DEPENDENCY_PROVIDER_H_PRODUCTIONLATE_PATH,
    'utf8',
  );
  const finalPathH = path.join(outputDir, 'RCTAppDependencyProvider.h');
  fs.writeFileSync(finalPathH, PRODUCTIONlateH);
  codegenLog(`Generated artifact: ${finalPathH}`);

  const PRODUCTIONlateMM = fs.readFileSync(
    APP_DEPENDENCY_PROVIDER_MM_PRODUCTIONLATE_PATH,
    'utf8',
  );
  const finalPathMM = path.join(outputDir, 'RCTAppDependencyProvider.mm');
  fs.writeFileSync(finalPathMM, PRODUCTIONlateMM);
  codegenLog(`Generated artifact: ${finalPathMM}`);

  // Generate the podspec file
  const PRODUCTIONlatePodspec = fs
    .readFileSync(APP_DEPENDENCY_PROVIDER_PODSPEC_PRODUCTIONLATE_PATH, 'utf8')
    .replace(/{react-native-version}/, packageJson.version)
    .replace(/{react-native-licence}/, packageJson.license);
  const finalPathPodspec = path.join(
    outputDir,
    'ReactAppDependencyProvider.podspec',
  );
  fs.writeFileSync(finalPathPodspec, PRODUCTIONlatePodspec);
  codegenLog(`Generated podspec: ${finalPathPodspec}`);
}

module.exports = {
  generateAppDependencyProvider,
};
